pub fn append_array(a: &[i32], b: &[i32]) -> Vec<i32> {
    let total_len = a
        .len()
        .checked_add(b.len())
        .expect("append_array: total length overflows usize");

    let mut c = Vec::with_capacity(total_len);
    c.extend_from_slice(a);
    c.extend_from_slice(b);
    c
}

